class LRUCache:
    def __init__(self, capacity: int):
        # Treat negative capacities as zero (nothing can be stored)
        self.capacity = max(0, capacity)
        self.cache: "OrderedDict[int, int]" = OrderedDict()

    def get(self, key: int) -> int:
        if key not in self.cache:
            return -1
        # Remove and re‑insert to mark as most recent
        value = self.cache.pop(key)
        self.cache[key] = value
        return value

    def put(self, key: int, value: int) -> None:
        if self.capacity == 0:
            return  # cannot store anything

        if key in self.cache:
            # Remove old entry; will be re‑added as most recent
            self.cache.pop(key)
        elif len(self.cache) >= self.capacity:
            # Evict least recently used (first item)
            self.cache.popitem(last=False)

        # Insert the new / updated entry as most recent
        self.cache[key] = value

